export type JsonSchema =
  | boolean
  | {
      [key: string]: unknown;
      type?: string | string[];
      properties?: Record<string, JsonSchema>;
      required?: string[];
      enum?: unknown[];
      description?: string;
      title?: string;
      items?: JsonSchema;
    };
export interface ToolDefinition {
  name: string;
  title?: string;
  description?: string;
  inputSchema: JsonSchema;
  annotations?: {
    readOnlyHint?: boolean;
    destructiveHint?: boolean;
    untrustedContentHint?: boolean;
    consequentialHint?: boolean;
    [key: string]: unknown;
  };
}
export interface Execution {
  id: string;
  name: string;
  source: "human" | "agent" | "simulator";
  status: "running" | "success" | "error" | "cancelled";
  startedAt: number;
  completedAt?: number;
  args: Record<string, unknown>;
  result?: unknown;
  error?: string;
  progress?: { progress: number; total?: number; message?: string };
}
export type Support = "checking" | "native" | "legacy" | "unsupported";
export interface ToolContext {
  signal: AbortSignal;
  source: Execution["source"];
}
export interface WebTool extends ToolDefinition {
  execute: (
    args: Record<string, unknown>,
    context: ToolContext,
  ) => unknown | Promise<unknown>;
}
export function errorMessage(error: unknown) {
  return error instanceof Error ? error.message : "The operation failed.";
}

import {
  Client,
  StreamableHTTPClientTransport,
  type OAuthClientProvider,
  type ClientOptions,
} from "@modelcontextprotocol/client";
export const MCP_PROTOCOL_VERSION = "2026-07-28";
export interface ConnectionOptions {
  endpoint: string;
  token?: string;
  oauth?: OAuthClientProvider;
  protocol?: "auto" | "current" | "legacy";
  fetch?: typeof fetch;
}
export function createMCPClient(
  options: ConnectionOptions,
  handlers: Pick<ClientOptions, "listChanged"> = {},
) {
  const url = new URL(
    options.endpoint,
    typeof location !== "undefined" ? location.origin : undefined,
  );
  if (
    url.username ||
    url.password ||
    url.hash ||
    !["https:", "http:"].includes(url.protocol)
  )
    throw new Error(
      "Use an HTTP(S) endpoint without embedded credentials or a fragment.",
    );
  if (
    url.protocol === "http:" &&
    !["localhost", "127.0.0.1", "[::1]"].includes(url.hostname)
  )
    throw new Error("Remote connections require HTTPS.");
  const client = new Client(
    { name: "fabrials-webmcp", version: "0.1.0" },
    {
      ...handlers,
      capabilities: { elicitation: { form: {}, url: {} } },
      versionNegotiation: {
        mode:
          options.protocol === "legacy"
            ? "legacy"
            : options.protocol === "current"
              ? { pin: MCP_PROTOCOL_VERSION }
              : "auto",
        probe: { timeoutMs: 10_000, maxRetries: 0 },
      },
      inputRequired: { maxRounds: 8 },
      listMaxPages: 64,
    },
  );
  const transport = new StreamableHTTPClientTransport(url, {
    authProvider:
      options.oauth ??
      (options.token ? { token: async () => options.token! } : undefined),
    fetch: options.fetch,
    reconnectionOptions: {
      maxRetries: 0,
      maxReconnectionDelay: 0,
      initialReconnectionDelay: 0,
      reconnectionDelayGrowFactor: 1,
    },
  });
  return { client, transport };
}

"use client";
import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useRef,
  useState,
  type ReactNode,
} from "react";
import type {
  Client,
  Tool,
  Resource,
  ResourceTemplateType,
  Prompt,
  ServerCapabilities,
  ElicitRequestParams,
  ElicitResult,
} from "@modelcontextprotocol/client";
import { createMCPClient, type ConnectionOptions } from "@/lib/mcp/client";
import { errorMessage, type Execution } from "@/lib/mcp/types";
export interface Elicitation {
  id: string;
  params: ElicitRequestParams;
  respond: (result: ElicitResult) => void;
}
function useConnection() {
  const clientRef = useRef<Client | null>(null);
  const generation = useRef(0);
  const active = useRef(new Map<string, AbortController>());
  const pendingInputs = useRef(
    new Map<string, (result: ElicitResult) => void>(),
  );
  const [status, setStatus] = useState<
    "disconnected" | "connecting" | "connected" | "error"
  >("disconnected");
  const [error, setError] = useState("");
  const [tools, setTools] = useState<Tool[]>([]);
  const [resources, setResources] = useState<Resource[]>([]);
  const [templates, setTemplates] = useState<ResourceTemplateType[]>([]);
  const [prompts, setPrompts] = useState<Prompt[]>([]);
  const [capabilities, setCapabilities] = useState<ServerCapabilities>({});
  const [protocol, setProtocol] = useState("");
  const [executions, setExecutions] = useState<Execution[]>([]);
  const [elicitations, setElicitations] = useState<Elicitation[]>([]);
  const disconnect = useCallback(async () => {
    generation.current++;
    active.current.forEach((c) => c.abort());
    active.current.clear();
    pendingInputs.current.forEach((resolve) => resolve({ action: "cancel" }));
    pendingInputs.current.clear();
    const old = clientRef.current;
    clientRef.current = null;
    setStatus("disconnected");
    setTools([]);
    setPrompts([]);
    setResources([]);
    setTemplates([]);
    setCapabilities({});
    setProtocol("");
    setElicitations([]);
    setExecutions([]);
    setError("");
    await old?.close();
  }, []);
  const refresh = useCallback(async () => {
    const client = clientRef.current;
    if (!client) return;
    const [t, r, p, rt] = await Promise.all([
      client.listTools(),
      client.listResources(),
      client.listPrompts(),
      client.listResourceTemplates(),
    ]);
    if (clientRef.current !== client) return;
    setTools(t.tools);
    setResources(r.resources);
    setPrompts(p.prompts);
    setTemplates(rt.resourceTemplates);
  }, []);
  const connect = useCallback(
    async (options: ConnectionOptions, callback?: URLSearchParams) => {
      await disconnect();
      const current = ++generation.current;
      setStatus("connecting");
      const belongs = () => generation.current === current;
      try {
        const { client, transport } = createMCPClient(options, {
          listChanged: {
            tools: {
              onChanged: (e, values) => {
                if (belongs()) {
                  if (e) setError(errorMessage(e));
                  else setTools(values ?? []);
                }
              },
            },
            prompts: {
              onChanged: (e, values) => {
                if (belongs()) {
                  if (e) setError(errorMessage(e));
                  else setPrompts(values ?? []);
                }
              },
            },
            resources: {
              onChanged: (e, values) => {
                if (belongs()) {
                  if (e) setError(errorMessage(e));
                  else setResources(values ?? []);
                }
              },
            },
          },
        });
        clientRef.current = client;
        client.setRequestHandler(
          "elicitation/create",
          (request, context) =>
            new Promise<ElicitResult>((resolve) => {
              const id = crypto.randomUUID();
              const respond = (result: ElicitResult) => {
                context.mcpReq.signal.removeEventListener("abort", abort);
                pendingInputs.current.delete(id);
                setElicitations((items) => items.filter((x) => x.id !== id));
                resolve(result);
              };
              const abort = () => respond({ action: "cancel" });
              if (context.mcpReq.signal.aborted) return abort();
              context.mcpReq.signal.addEventListener("abort", abort, {
                once: true,
              });
              pendingInputs.current.set(id, respond);
              setElicitations((items) => [
                ...items,
                { id, params: request.params, respond },
              ]);
            }),
        );
        client.onerror = (e) => {
          if (belongs()) setError(errorMessage(e));
        };
        client.onclose = () => {
          if (belongs()) {
            setStatus("disconnected");
            active.current.forEach((c) => c.abort());
            pendingInputs.current.forEach((resolve) =>
              resolve({ action: "cancel" }),
            );
          }
        };
        if (callback) await transport.finishAuth(callback);
        await client.connect(transport);
        if (!belongs()) {
          await client.close();
          return;
        }
        setCapabilities(client.getServerCapabilities() ?? {});
        setProtocol(client.getNegotiatedProtocolVersion() ?? "");
        await refresh();
        if (belongs()) setStatus("connected");
      } catch (e) {
        if (belongs()) {
          const failed = clientRef.current;
          clientRef.current = null;
          await failed?.close().catch(() => {});
          setError(errorMessage(e));
          setStatus("error");
        }
      }
    },
    [disconnect, refresh],
  );
  const run = useCallback(
    async (name: string, args: Record<string, unknown>) => {
      const client = clientRef.current;
      if (!client || status !== "connected")
        throw new Error("Connect to a server first.");
      const id = crypto.randomUUID();
      const controller = new AbortController();
      active.current.set(id, controller);
      setExecutions((items) =>
        [
          {
            id,
            name,
            args,
            source: "human" as const,
            status: "running" as const,
            startedAt: Date.now(),
          },
          ...items,
        ].slice(0, 100),
      );
      const update = (patch: Partial<Execution>) =>
        setExecutions((items) =>
          items.map((e) => (e.id === id ? { ...e, ...patch } : e)),
        );
      try {
        const result = await client.callTool(
          { name, arguments: args },
          {
            signal: controller.signal,
            timeout: 120_000,
            onprogress: (progress) => update({ progress }),
          },
        );
        update({
          status: result.isError ? "error" : "success",
          result,
          completedAt: Date.now(),
        });
        return result;
      } catch (e) {
        update({
          status: controller.signal.aborted ? "cancelled" : "error",
          error: errorMessage(e),
          completedAt: Date.now(),
        });
        throw e;
      } finally {
        active.current.delete(id);
      }
    },
    [status],
  );
  useEffect(
    () => () => {
      generation.current++;
      active.current.forEach((c) => c.abort());
      pendingInputs.current.forEach((resolve) => resolve({ action: "cancel" }));
      void clientRef.current?.close();
    },
    [],
  );
  return {
    status,
    error,
    tools,
    resources,
    templates,
    prompts,
    capabilities,
    protocol,
    executions,
    elicitations,
    connect,
    disconnect,
    refresh,
    run,
    cancel: (id: string) => active.current.get(id)?.abort(),
    clearHistory: () =>
      setExecutions((items) => items.filter((e) => e.status === "running")),
    readResource: async (uri: string) => {
      if (!clientRef.current) throw new Error("Not connected.");
      return clientRef.current.readResource({ uri });
    },
    getPrompt: async (name: string, args: Record<string, string>) => {
      if (!clientRef.current) throw new Error("Not connected.");
      return clientRef.current.getPrompt({ name, arguments: args });
    },
  };
}
const Context = createContext<ReturnType<typeof useConnection> | null>(null);
export function MCPProvider({ children }: { children: ReactNode }) {
  const value = useConnection();
  return <Context.Provider value={value}>{children}</Context.Provider>;
}
export function useMCPClient() {
  const value = useContext(Context);
  if (!value) throw new Error("Wrap this component in MCPProvider.");
  return value;
}

import type {
  OAuthClientProvider,
  OAuthClientMetadata,
  StoredOAuthClientInformation,
  StoredOAuthTokens,
  OAuthClientInformationContext,
  OAuthDiscoveryState,
} from "@modelcontextprotocol/client";
const PREFIX = "fabrials.webmcp.oauth";
type Pending = {
  endpoint: string;
  returnPath: string;
  state: string;
  createdAt: number;
  verifier?: string;
  discovery?: OAuthDiscoveryState;
  clients: Record<string, StoredOAuthClientInformation>;
  clientId?: string;
};
export class BrowserOAuthProvider implements OAuthClientProvider {
  private tokenSets = new Map<string, StoredOAuthTokens>();
  private lastIssuer = "";
  private pending: Pending;
  readonly redirectUrl: string;
  readonly clientMetadataUrl: string;
  constructor(
    readonly endpoint: string,
    options: {
      callbackPath?: string;
      metadataPath?: string;
      clientId?: string;
      resume?: boolean;
    } = {},
  ) {
    this.redirectUrl = new URL(
      options.callbackPath ?? "/oauth/callback",
      location.origin,
    ).href;
    this.clientMetadataUrl = new URL(
      options.metadataPath ?? "/oauth/client-metadata.json",
      location.origin,
    ).href;
    const saved = options.resume
      ? BrowserOAuthProvider.readPending()
      : undefined;
    if (options.resume && (!saved || saved.endpoint !== endpoint))
      throw new Error("OAuth session expired. Start a new connection.");
    this.pending = saved ?? {
      endpoint,
      returnPath: location.pathname,
      state: crypto.randomUUID(),
      createdAt: Date.now(),
      clients: {},
      clientId: options.clientId,
    };
  }
  static readPending(): Pending | undefined {
    try {
      const saved = JSON.parse(
        sessionStorage.getItem(PREFIX) ?? "null",
      ) as Pending | null;
      if (saved && Date.now() - saved.createdAt < 10 * 60_000) return saved;
    } catch {
      /* Invalid transient state is discarded. */
    }
    sessionStorage.removeItem(PREFIX);
  }
  private save() {
    sessionStorage.setItem(PREFIX, JSON.stringify(this.pending));
  }
  get clientMetadata(): OAuthClientMetadata {
    return {
      client_name: "Fabrials WebMCP UI",
      redirect_uris: [this.redirectUrl],
      grant_types: ["authorization_code", "refresh_token"],
      response_types: ["code"],
      token_endpoint_auth_method: "none",
      application_type: "web",
    };
  }
  state = () => this.pending.state;
  clientInformation = (ctx?: OAuthClientInformationContext) =>
    this.pending.clientId
      ? { client_id: this.pending.clientId }
      : this.pending.clients[ctx?.issuer ?? ""];
  saveClientInformation = (
    value: StoredOAuthClientInformation,
    ctx?: OAuthClientInformationContext,
  ) => {
    this.pending.clients[ctx?.issuer ?? ""] = value;
    this.save();
  };
  tokens = (ctx?: OAuthClientInformationContext) =>
    this.tokenSets.get(ctx?.issuer ?? this.lastIssuer);
  saveTokens = (
    value: StoredOAuthTokens,
    ctx?: OAuthClientInformationContext,
  ) => {
    this.lastIssuer = ctx?.issuer ?? "";
    this.tokenSets.set(this.lastIssuer, value);
  };
  saveCodeVerifier = (value: string) => {
    this.pending.verifier = value;
    this.save();
  };
  codeVerifier = () => {
    if (!this.pending.verifier)
      throw new Error("Missing PKCE verifier. Restart authorization.");
    return this.pending.verifier;
  };
  saveDiscoveryState = (value: OAuthDiscoveryState) => {
    this.pending.discovery = value;
    this.save();
  };
  discoveryState = () => this.pending.discovery;
  redirectToAuthorization = (url: URL) => {
    this.save();
    location.assign(url.href);
  };
  validateCallback(params: URLSearchParams) {
    if (params.get("state") !== this.pending.state)
      throw new Error("OAuth state mismatch. Restart authorization.");
    if (Date.now() - this.pending.createdAt > 600_000)
      throw new Error("OAuth session expired.");
    if (params.has("error"))
      throw new Error(`Authorization declined: ${params.get("error")}`);
    if (!params.get("code")) throw new Error("No authorization code returned.");
  }
  complete() {
    delete this.pending.verifier;
    sessionStorage.removeItem(PREFIX);
  }
  invalidateCredentials = (
    scope: "all" | "client" | "tokens" | "verifier" | "discovery",
  ) => {
    if (scope === "all" || scope === "tokens") this.tokenSets.clear();
    if (scope === "all" || scope === "client") this.pending.clients = {};
    if (scope === "all" || scope === "verifier") delete this.pending.verifier;
    if (scope === "all" || scope === "discovery") delete this.pending.discovery;
    if (scope === "all") sessionStorage.removeItem(PREFIX);
    else this.save();
  };
}

"use client";
import { useId, useState } from "react";
import { Plug, Unplug } from "lucide-react";
import { Badge, Button, Input, Label, NativeSelect } from "@fabrials/ui";
import { BrowserOAuthProvider } from "@/lib/mcp/oauth";
import type { ConnectionOptions } from "@/lib/mcp/client";
export function ConnectionPanel({
  status,
  error,
  protocol,
  onConnect,
  onDisconnect,
  defaultEndpoint = "",
}: {
  status: string;
  error?: string;
  protocol?: string;
  onConnect: (options: ConnectionOptions) => Promise<void>;
  onDisconnect: () => Promise<void>;
  defaultEndpoint?: string;
}) {
  const id = useId();
  const [endpoint, setEndpoint] = useState(defaultEndpoint);
  const [auth, setAuth] = useState("none");
  const [token, setToken] = useState("");
  const [clientId, setClientId] = useState("");
  const [version, setVersion] = useState<"auto" | "current" | "legacy">("auto");
  const [localError, setLocalError] = useState("");
  const connected = status === "connected";
  const busy = status === "connecting";
  return (
    <form
      className="space-y-4"
      onSubmit={async (e) => {
        e.preventDefault();
        setLocalError("");
        try {
          const url = new URL(endpoint, location.origin).href;
          const secret = token;
          setToken("");
          await onConnect({
            endpoint: url,
            token: auth === "bearer" ? secret : undefined,
            oauth:
              auth === "oauth"
                ? new BrowserOAuthProvider(url, {
                    clientId: clientId || undefined,
                  })
                : undefined,
            protocol: version,
          });
        } catch (e) {
          setLocalError(e instanceof Error ? e.message : "Connection failed.");
        }
      }}
    >
      <div className="flex flex-wrap items-center justify-between gap-2">
        <h3 className="text-sm font-medium">Server connection</h3>
        <Badge variant="outline" role="status">
          {status}
          {protocol && ` · ${protocol}`}
        </Badge>
      </div>
      <div className="space-y-1.5">
        <Label htmlFor={`${id}-url`}>MCP endpoint</Label>
        <Input
          id={`${id}-url`}
          value={endpoint}
          onChange={(e) => setEndpoint(e.target.value)}
          placeholder="https://your-server.com/mcp"
          required
          disabled={connected || busy}
        />
      </div>
      <div className="grid grid-cols-2 gap-3">
        <div className="space-y-1.5">
          <Label htmlFor={`${id}-auth`}>Authentication</Label>
          <NativeSelect
            id={`${id}-auth`}
            value={auth}
            onChange={(e) => {
              setAuth(e.target.value);
              setToken("");
            }}
            disabled={connected || busy}
          >
            <option value="none">None</option>
            <option value="bearer">Bearer token</option>
            <option value="oauth">OAuth / PKCE</option>
          </NativeSelect>
        </div>
        <div className="space-y-1.5">
          <Label htmlFor={`${id}-version`}>Protocol</Label>
          <NativeSelect
            id={`${id}-version`}
            value={version}
            onChange={(e) => setVersion(e.target.value as typeof version)}
            disabled={connected || busy}
          >
            <option value="auto">Auto · prefer latest</option>
            <option value="current">2026-07-28</option>
            <option value="legacy">Legacy handshake</option>
          </NativeSelect>
        </div>
      </div>
      {auth === "bearer" && !connected && (
        <div className="space-y-1.5">
          <Label htmlFor={`${id}-token`}>Token · memory only</Label>
          <Input
            id={`${id}-token`}
            type="password"
            autoComplete="off"
            value={token}
            onChange={(e) => setToken(e.target.value)}
            required
          />
        </div>
      )}
      {auth === "oauth" && !connected && (
        <div className="space-y-1.5">
          <Label htmlFor={`${id}-client`}>Client ID (optional)</Label>
          <Input
            id={`${id}-client`}
            value={clientId}
            onChange={(e) => setClientId(e.target.value)}
            placeholder="Use discovery by default"
          />
        </div>
      )}
      {(error || localError) && (
        <p role="alert" className="text-sm text-destructive">
          {localError || error}
        </p>
      )}
      <div className="flex gap-2">
        {connected ? (
          <Button
            variant="outline"
            type="button"
            onClick={() => {
              setToken("");
              void onDisconnect();
            }}
          >
            <Unplug />
            Disconnect
          </Button>
        ) : (
          <Button type="submit" disabled={busy}>
            <Plug />
            {busy ? "Connecting…" : "Connect server"}
          </Button>
        )}
        {busy && (
          <Button
            variant="outline"
            type="button"
            onClick={() => void onDisconnect()}
          >
            Cancel
          </Button>
        )}
      </div>
      <p className="text-xs leading-relaxed text-muted-foreground">
        Direct connections stay in your browser. The endpoint must allow CORS.
        Use the optional server connector for private credentials.
      </p>
    </form>
  );
}

import Ajv2020 from "ajv/dist/2020.js";
import addFormats from "ajv-formats";
import type { JsonSchema } from "@/lib/mcp/types";
const ajv = new Ajv2020({
  allErrors: true,
  strict: false,
  validateFormats: true,
  validateSchema: true,
});
addFormats(ajv);
export function validateArguments(
  schema: JsonSchema,
  value: unknown,
): string | null {
  try {
    const validate = ajv.compile(schema);
    if (validate(value)) return null;
    return (validate.errors ?? [])
      .map((e) => `${e.instancePath || "Input"} ${e.message}`)
      .join("; ");
  } catch {
    return "This schema cannot be validated locally. Provide a self-contained JSON Schema 2020-12 without external references.";
  }
}
export function simpleFields(
  schema: JsonSchema,
): schema is Exclude<JsonSchema, boolean> {
  if (
    !schema ||
    typeof schema !== "object" ||
    Array.isArray(schema) ||
    schema.type !== "object"
  )
    return false;
  if (
    schema.properties &&
    (typeof schema.properties !== "object" || Array.isArray(schema.properties))
  )
    return false;
  if (
    Object.keys(schema).some((k) =>
      [
        "$ref",
        "allOf",
        "anyOf",
        "oneOf",
        "if",
        "dependentSchemas",
        "patternProperties",
      ].includes(k),
    )
  )
    return false;
  return Object.values(schema.properties ?? {}).every(
    (p) =>
      p !== null &&
      typeof p === "object" &&
      !Array.isArray(p) &&
      ["string", "number", "integer", "boolean"].includes(String(p.type)) &&
      !p.$ref &&
      !p.anyOf &&
      !p.oneOf &&
      !p.allOf,
  );
}

"use client";
import { useId, useState } from "react";
import {
  Button,
  Input,
  Label,
  NativeCheckbox,
  NativeSelect,
  Textarea,
} from "@fabrials/ui";
import { simpleFields, validateArguments } from "@/lib/mcp/schema";
import { errorMessage, type JsonSchema } from "@/lib/mcp/types";
export function ArgumentsForm({
  schema,
  onSubmit,
  submitLabel = "Run tool",
  disabled = false,
  initialValues = {},
}: {
  schema: JsonSchema;
  onSubmit: (args: Record<string, unknown>) => unknown | Promise<unknown>;
  submitLabel?: string;
  disabled?: boolean;
  initialValues?: Record<string, unknown>;
}) {
  const id = useId();
  const [error, setError] = useState("");
  const [pending, setPending] = useState(false);
  const fields = simpleFields(schema) ? (schema.properties ?? {}) : null;
  const [json, setJson] = useState(JSON.stringify(initialValues, null, 2));
  return (
    <form
      className="space-y-4"
      onSubmit={async (event) => {
        event.preventDefault();
        if (pending || disabled) return;
        const data = new FormData(event.currentTarget);
        setError("");
        try {
          let args: Record<string, unknown>;
          if (!fields) args = JSON.parse(json);
          else {
            args = {};
            for (const [name, field] of Object.entries(fields)) {
              if (typeof field === "boolean") continue;
              const raw = data.get(name);
              const required =
                typeof schema !== "boolean" && schema.required?.includes(name);
              if (field.type === "boolean") {
                args[name] = field.enum ? raw === "true" : raw === "on";
                continue;
              }
              if (raw === "" && !required) continue;
              args[name] =
                field.type === "number" || field.type === "integer"
                  ? Number(raw)
                  : String(raw ?? "");
            }
          }
          if (!args || typeof args !== "object" || Array.isArray(args))
            throw new Error("Arguments must be a JSON object.");
          const invalid = validateArguments(schema, args);
          if (invalid) throw new Error(invalid);
          setPending(true);
          await onSubmit(args);
        } catch (e) {
          setError(errorMessage(e));
        } finally {
          setPending(false);
        }
      }}
    >
      {fields ? (
        Object.entries(fields).map(([name, field]) => {
          if (typeof field === "boolean") return null;
          const required =
            typeof schema !== "boolean" && schema.required?.includes(name);
          const fieldId = `${id}-${name}`;
          return (
            <div className="space-y-1.5" key={name}>
              <Label htmlFor={fieldId}>
                {field.title ?? name}
                {required && (
                  <span aria-label="required" className="text-muted-foreground">
                    *
                  </span>
                )}
              </Label>
              {field.enum ? (
                <NativeSelect
                  id={fieldId}
                  name={name}
                  required={required}
                  defaultValue={String(
                    initialValues[name] ?? field.default ?? "",
                  )}
                  disabled={pending || disabled}
                >
                  <option value="">Select…</option>
                  {field.enum.map((value, index) => (
                    <option key={index} value={String(value)}>
                      {String(value)}
                    </option>
                  ))}
                </NativeSelect>
              ) : field.type === "boolean" ? (
                <NativeCheckbox
                  id={fieldId}
                  name={name}
                  defaultChecked={Boolean(initialValues[name] ?? field.default)}
                  disabled={pending || disabled}
                />
              ) : (
                <Input
                  id={fieldId}
                  name={name}
                  type={
                    ["integer", "number"].includes(String(field.type))
                      ? "number"
                      : field.format === "date"
                        ? "date"
                        : field.format === "email"
                          ? "email"
                          : "text"
                  }
                  step={field.type === "integer" ? 1 : "any"}
                  min={
                    typeof field.minimum === "number"
                      ? field.minimum
                      : undefined
                  }
                  max={
                    typeof field.maximum === "number"
                      ? field.maximum
                      : undefined
                  }
                  required={required}
                  defaultValue={String(
                    initialValues[name] ?? field.default ?? "",
                  )}
                  disabled={pending || disabled}
                  aria-describedby={
                    field.description ? `${fieldId}-help` : undefined
                  }
                />
              )}
              {field.description && (
                <p
                  id={`${fieldId}-help`}
                  className="text-xs text-muted-foreground"
                >
                  {field.description}
                </p>
              )}
            </div>
          );
        })
      ) : (
        <div className="space-y-2">
          <Label htmlFor={id}>Arguments · JSON</Label>
          <Textarea
            id={id}
            value={json}
            onChange={(e) => setJson(e.target.value)}
            rows={8}
            spellCheck={false}
            className="font-mono text-xs"
            disabled={pending || disabled}
          />
          <p className="text-xs text-muted-foreground">
            This schema uses advanced JSON Schema features. Edit its arguments
            directly.
          </p>
        </div>
      )}
      {error && (
        <p role="alert" className="text-sm text-destructive">
          {error}
        </p>
      )}
      <Button type="submit" disabled={disabled || pending} aria-busy={pending}>
        {pending ? "Running…" : submitLabel}
      </Button>
    </form>
  );
}

